def create_existing_skus(apps, schema_editor):
    """Create identities only; current quantities cannot establish past movements."""
    Product = apps.get_model('api', 'Product')
    InventorySKU = apps.get_model('api', 'InventorySKU')
    using = schema_editor.connection.alias
    for product in Product.objects.using(using).iterator(chunk_size=500):
        keys = {('', '')}
        if product.product_type != 'bundle':
            for group in product.customization_options or []:
                if not isinstance(group, dict):
                    continue
                for option in group.get('options') or []:
                    if isinstance(option, dict) and 'stock' in option:
                        keys.add((str(group.get('name') or ''), str(option.get('name') or '')))
        prefix = 'BND' if product.product_type == 'bundle' else (slugify(product.name).replace('-', '')[:3].upper() or 'ITM')
        InventorySKU.objects.using(using).bulk_create([
            InventorySKU(product_id=product.pk, group_name=group, variant_name=name, prefix=prefix,
                variant_code=''.join(word[0] for word in slugify(name).split('-') if word)[:4].upper())
            for group, name in sorted(keys)
        ])


